/// The model and texture for an entity kind, such as `minecraft:cow`.
pub fn look(kind: &str) -> Option<(&'static Model, &'static str)> {
    let (_, key, texture) = LOOKS.iter().find(|(name, ..)| *name == kind)?;
    Some((model(key)?, texture))
}
